import numpy as np
from numba import njit

@njit(cache=True)
def _assignment(a):
    n = a.shape[0]
    u = np.zeros(n + 1)
    v = np.zeros(n + 1)
    p = np.zeros(n + 1, np.int64)
    way = np.zeros(n + 1, np.int64)
    minv = np.empty(n + 1)
    used = np.empty(n + 1, np.uint8)
    for i in range(1, n + 1):
        p[0] = i
        for j in range(n + 1):
            minv[j] = np.inf
            used[j] = 0
        j0 = 0
        while True:
            used[j0] = 1
            i0 = p[j0]
            delta = np.inf
            j1 = 0
            for j in range(1, n + 1):
                if used[j] == 0:
                    cur = a[i0-1, j-1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(n + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break
    ans = np.empty(n, np.int64)
    for j in range(1, n + 1):
        ans[p[j]-1] = j-1
    return ans

class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem['source_weights'])
        b = np.asarray(problem['target_weights'])
        M = np.asarray(problem['cost_matrix'])
        n, m = M.shape
        if n == m and np.all(a == a[0]) and np.all(b == b[0]) and abs(float(a[0])-float(b[0])) < 1e-15:
            cols = _assignment(M)
            G = np.zeros((n, n))
            G[np.arange(n), cols] = a[0]
            return {'transport_plan': G}
        import ot
        return {'transport_plan': ot.lp.emd(a, b, np.ascontiguousarray(M, dtype=np.float64), check_marginals=False)}
