"""Fast exact uniform optimal transport via a sparse auction assignment."""
import numpy as np
from numba import njit

@njit(cache=True)
def _auction(C, choices):
 n=C.shape[0]; k=choices.shape[1]
 price=np.zeros(n); owner=np.empty(n,np.int32); ass=np.empty(n,np.int32); stack=np.empty(n,np.int32)
 eps=.01
 while eps>1e-12:
  owner[:]=-1; ass[:]=-1
  for i in range(n): stack[i]=i
  top=n
  while top:
   top-=1;i=stack[top]; best=1e300;second=1e300;bj=0
   for q in range(k):
    j=choices[i,q];x=C[i,j]+price[j]
    if x<best:second=best;best=x;bj=j
    elif x<second:second=x
   price[bj]+=second-best+eps;old=owner[bj];owner[bj]=i;ass[i]=bj
   if old>=0:stack[top]=old;top+=1
  eps*=.1
 return ass,price

class Solver:
 def solve(self,problem,**kwargs):
  a=np.asarray(problem['source_weights']);b=np.asarray(problem['target_weights']);M=np.asarray(problem['cost_matrix']);n,m=M.shape
  if n==m and n and np.all(a==a[0]) and np.all(b==b[0]) and abs(float(a[0]-b[0]))<=1e-15:
   k=min(120,n); ix=np.argpartition(M,k-1,axis=1)[:,:k]; cols,price=_auction(M,ix)
   # Dual/complementary-slackness certificate against every original edge.
   chosen=M[np.arange(n),cols]+price[cols]
   if np.any(chosen-np.min(M+price,axis=1)>5e-11):
    ix=np.broadcast_to(np.arange(n),(n,n));cols,price=_auction(M,ix)
   G=np.zeros((n,n));G[np.arange(n),cols]=a[0];return {'transport_plan':G}
  import ot
  return {'transport_plan':ot.lp.emd(a,b,np.ascontiguousarray(M,dtype=np.float64),check_marginals=False)}
